"""Rev G vs Rev H wellhead example comparison table (Markdown + JSON).

Usage: rev_h_compare_wellhead.py REV_G_SUMMARY.json REV_H_SUMMARY.json REV_H_OPT1M_SUMMARY.json ELIGIBLE_CHECK.json OUT_PREFIX
REV_H_OPT1M is a Rev H build whose options study used the Rev G 1.0 m options grid; it
separates method changes from the F25 grid change. Values are copied, never edited.
"""
import json,sys
g,h,h1,chk=(json.load(open(p)) for p in sys.argv[1:5]);out=sys.argv[5]
chk={r['zone']:r for r in chk}
FL='F01 exact free measure + representative free point; F05 LOS from detector (Rev G trimmed 0.05 m standoff from every ray); F06 eps-consistent broadphase'
GS='F01 exact free measure + representative free point (point-gas votes do not use LOS); open-path beams via F05/F06 rules'
rows=[]
def add(z,m,a,b,why,ev):rows.append({'zone':z,'metric':m,'rev_g':a,'rev_h':b,'reason':why,'evidence':ev})
for z in h['zones']:
    G=g['zones'][z];H=h['zones'][z];c=chk[z];kind=FL if z.startswith('FZ') else GS
    add(z,'method',G['method'],H['method'],'Method version bump for F01-F07 changes','docs/METHOD_AND_TOLERANCES_REV_H.md')
    add(z,'eligible m3','%.4f' % G['eligible_m3'],'%.4f' % H['eligible_m3'],'F01: Rev G took whole cells in or out by centre; Rev H integrates exact free volume of each cell','Independent slab-sweep exact volume (tools/rev_h_independent_eligible_check.py, no fgmapping import) = %.4f m3, abs diff %.1e; Monte Carlo %.1f m3 (n=%d)' % (c['independent_free_exact'],c['abs_diff'],c['monte_carlo_free'],c['mc_samples']))
    add(z,'inside obstruction m3','%.4f' % G['excluded_m3']['inside_obstruction'],'%.4f' % H['excluded_m3']['inside_obstruction'],'F01 exact solid volume within zone','zone volume %.4f = eligible + obstruction + excluded (closure check)' % c['zone_volume'])
    add(z,'excluded component m3','%.4f' % G['excluded_m3']['excluded_component'],'%.4f' % H['excluded_m3']['excluded_component'],'F01/F03 exact mesh-based exclusion (Rev G: centre test against AABB)','same independent check')
    for k in ('0ooN','1ooN','2ooN'):
        add(z,k,'%.4f' % G[k],'%.4f' % H[k],kind,'Analytic regression tests tests/unit/test_rev_h_numerical.py + review probes 02_REVIEW_PROBES_AFTER; deterministic across two Rev H rebuilds')
    for k in ('1ooN','2ooN'):
        if G['targets'][k]!=H['targets'][k]:add(z,'target '+k,G['targets'][k],H['targets'][k],'follows fraction change','-')
    add(z,'grid check',G['convergence'],H['convergence'],'F07: two-grid agreement is not an error bound; label changed, unresolved-feature and empty-denominator states added','probe false_convergence -> UNRESOLVED FEATURE; empty_denominator -> NOT EVALUABLE')
S=('scenarios','overall','frequency_weighted_detected_fraction')
add('WHM-SCN-A','frequency-weighted detected fraction',g['studies']['scenarios']['overall'][S[2]],h['studies']['scenarios']['overall'][S[2]],'unchanged: scenario points are far from geometry edges; Decimal now in local context (F23)','tests F23; integrity probe changed_study_source -> STALE (F08)')
og,oh,o1=g['studies']['options'],h['studies']['options'],h1['studies']['options']
add('WHM-OPT-A FZ-MANIFOLD','existing layout 2ooN',og['existing_layout_2ooN'][:8]+' (1.0 m grid)',oh['existing_layout_2ooN'][:8]+' (0.5 m = zone grid)','F25: options now at the zone-run grid; method fixes alone give %s at 1.0 m' % o1['existing_layout_2ooN'][:8],'equals zone run FZ-MANIFOLD 2ooN %.6f' % h['zones']['FZ-MANIFOLD']['2ooN'])
def best(o,c):
    for a in o['pareto']:
        if a['cost']==c:return '+'.join(a['mount_ids']) or '(none)','%s' % a['fraction'][:8]
    return '-','-'
for c in ('1','2'):
    bg,bh,b1=best(og,c),best(oh,c),best(o1,c)
    add('WHM-OPT-A FZ-MANIFOLD','best cost-%s proposal' % c,'%s %s (1.0 m)' % bg,'%s %s (0.5 m)' % bh,'F25 common resolution (Rev H at 1.0 m gives %s %s); the 0.5 m ranking differs from the 1.0 m ranking' % b1,'resolution_note in options result; exhaustive Pareto test (F16)')
json.dump(rows,open(out+'.json','w'),indent=1)
with open(out+'.md','w') as f:
    f.write('# Wellhead example: Rev G vs Rev H (repaired)\n\nEXAMPLE library values and EXAMPLE targets - illustrative only, not for design. COMPUTED - UNREVIEWED development results - not independently verified.\nSame inputs, same host, 0.5 m VOLUME grid, refinement 2. Generated by tools/rev_h_compare_wellhead.py.\n\n| Zone | Metric | Rev G value | Repaired (Rev H) value | Reason | Independent evidence |\n|---|---|---|---|---|---|\n')
    for r in rows:f.write('| %s |\n' % ' | '.join(str(r[k]).replace('|','/') for k in ('zone','metric','rev_g','rev_h','reason','evidence')))
    f.write('\nNote: per-fix attribution of each fraction delta was not isolated by separate runs; the wellhead has roll 0 and symmetric 90x90 FOV, so F04 does not affect it, and no detector has a mount component, so F05 here means LOS now starts at the detector rather than 0.05 m along the ray.\n')
print(len(rows))
